        "privacy-tag": "POLITIQUE DE CONFIDENTIALITÉ",
        "privacy-title": "Politique de confidentialité",
        "privacy-subtitle":
          "Comment nous collectons, utilisons et protégeons vos informations personnelles à Sueño Del Mar Surf School.",
        "privacy-last-updated": "Dernière mise à jour :",
        "privacy-toc-title": "Sommaire",
        "privacy-toc-1": "Qui nous sommes",
        "privacy-toc-2": "Données collectées",
        "privacy-toc-3": "Utilisation des données",
        "privacy-toc-4": "Partage des données",
        "privacy-toc-5": "Conservation des données",
